# julia --startup-file=no --project=. -t1 benchmark/soft_realtime_calibration.jl
# Timings are warm serial call durations.
using AdaptiveOpticsCalibration
using LinearAlgebra
import AdaptiveOpticsCalibration: allocate_result, allocate_workspace
import AdaptiveOpticsCalibration.DOCRIME as DC
import AdaptiveOpticsCalibration.OpticalGains as OG
import AdaptiveOpticsCalibration.FocalPlaneSharpening as FS

function covariance_comparison()
    # A finite excitation window can have nonzero realized mean even when
    # generated by a zero-mean law. The last sample unbalances the four signs.
    commands = [-1.0 -1 1 1 1; -1.0 1 -1 1 1]
    truth = [2.0 -1; 0.5 3]
    spec = DC.CovarianceSpecification(2, 2)
    plan = prepare(DC.CenteredCovariance(), spec)
    work = allocate_workspace(plan)
    solver = prepare(DC.OpenLoop(DC.ConditioningCriteria(0.01, 0.9, 0.01)), spec)
    for baseline in ([0.0, 0.0], [32.0, -16.0])
        measured = truth * commands .+ baseline
        state = DC.CovarianceState(plan)
        for (m, c) in zip(eachcol(measured), eachcol(commands))
            process!(state, work, plan, DC.CovarianceSample(m, c))
        end
        solved = process(solver, DC.CovarianceSums(state))
        @assert solved.diagnostics.status == DC.Valid
        centered_error = norm(solved.matrix - truth) / norm(truth)
        # pyRTC Loop.docrimeIM at 1c0a55e uses uncentered cross and auto
        # moments. Evaluate that equation on the exact same aligned samples.
        raw = (measured * commands') / (commands * commands')
        raw_error = norm(raw - truth) / norm(truth)
        @assert centered_error < 1e-13
        println("baseline=", baseline, " centered_relative_error=", centered_error,
                " raw_moment_relative_error=", raw_error)
    end
end

function report_times(step!; samples=2000)
    for _ in 1:64
        step!()
    end
    bytes = @allocated step!()
    times = Vector{UInt64}(undef, samples)
    for i in eachindex(times)
        before = time_ns()
        step!()
        times[i] = time_ns() - before
    end
    sort!(times)
    println("samples=", samples, " p50_ns=", times[cld(samples, 2)],
            " p99_ns=", times[cld(99 * samples, 100)], " max_ns=", last(times),
            " bytes_per_call=", bytes)
end

function covariance_timing(m, c)
    plan = prepare(DC.CenteredCovariance(), DC.CovarianceSpecification(m, c))
    state = DC.CovarianceState(plan)
    work = allocate_workspace(plan)
    measurement = Float64.(1:m) ./ m
    command = Float64.(1:c) ./ c
    positive = DC.CovarianceSample(measurement, command)
    negative = DC.CovarianceSample(-measurement, -command)
    step!() = process!(state, work, plan, iseven(state.sample_count) ? positive : negative)
    println("covariance update: measurements=", m, " correctors=", c)
    report_times(step!)
    # Check the alternating sequence's centered end-coordinate cross sum.
    n = state.sample_count
    @assert state.measurement_corrector_cross_covariance_sum[end, end] ≈ n - isodd(n) / n
end

function dither_timing()
    times = range(0.0; step=0.001, length=128)
    frequencies = [12.5, 17.0, 21.0, 26.5, 31.0, 38.0, 41.5, 49.0]
    plan = prepare(OG.ModalDitherResponse(command_amplitude_floor=0.1),
        OG.ModalDitherResponseSpecification(frequencies, times; sample_rate=1000))
    commands = [3 + cos(2π*f*t) for t in times, f in frequencies]
    responses = [5 + 0.8cos(2π*f*t - 0.3) for t in times, f in frequencies]
    input = OG.ModalDitherResponseInputs(commands, responses)
    work, result = allocate_workspace(plan), allocate_result(plan)
    println("dither window: frames=128 modes=8")
    report_times(() -> process!(result, work, plan, input))
    @assert all(result.valid)
    @assert maximum(abs, result.gains .- 0.8) < 1e-12
    @assert maximum(abs, result.phase_lags .- 0.3) < 1e-12
end

function scan_timing()
    amplitudes = repeat(range(-1, 1; length=20), 3)
    metrics = @. 32 - (amplitudes - 0.375)^2
    plan = prepare(FS.ModalScan(), FS.ModalScanSpecification(amplitudes))
    result = allocate_result(plan)
    println("quadratic modal scan: samples=60")
    report_times(() -> process!(result, nothing, plan, metrics))
    @assert result.status == FS.Valid && abs(result.peak_amplitude - 0.375) < 1e-12
end

BLAS.set_num_threads(1)
println("Julia=", VERSION, " CPU=", Sys.CPU_NAME, " threads=", Threads.nthreads(),
        " BLAS_threads=", BLAS.get_num_threads())
covariance_comparison()
covariance_timing(376, 212)
dither_timing()
scan_timing()
